    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 80-year-old female named Dorothy presents to the resuscitation bay in severe respiratory distress. The patient has a history of congestive heart failure. Vitals are BP 218/118 mmHg, HR 132 bpm, RR 22 rpm, and SpO2 91% on room air. The patient is sitting upright, using accessory muscles, and has diffuse crackles bilaterally and jugular venous distention. Which of the following represents the most appropriate initial therapy?', '["Intubate the patient immediately and administer intravenous loop diuretics", "Administer high-flow oxygen via non-rebreather mask and intravenous morphine 4 mg", "Administer intravenous nitroprusside infusion and normal saline bolus", "Initiate non-invasive positive pressure ventilation (BiPAP/CPAP) and administer intravenous nitroglycerin", "Administer albuterol-ipratropium nebulizer and oral metoprolol 25 mg"]'::jsonb, 3, 'The patient is presenting with Acute Decompensated Heart Failure (ADHF) with acute pulmonary edema and sympathetic crash. The first-line therapeutic goals are to reduce work of breathing and decrease preload/afterload. Non-invasive positive pressure ventilation (NIPPV: CPAP or BiPAP) is highly effective: it increases intrathoracic pressure, reducing preload, and recruits collapsed alveoli, improving oxygenation. Intravenous nitroglycerin acts as a powerful venodilator to reduce preload and, at higher doses, an afterload reducer. Morphine should be avoided. (Ref: Tintinalli''s Ch. 53; Step-Up to EM Ch. 2; Case Files: EM Case 3)'),
    (v_topic_id, 'A 50-year-old male named Jacob presents to the bedside monitor area in severe respiratory distress. The patient has a history of congestive heart failure. Vitals are BP 224/122 mmHg, HR 114 bpm, RR 22 rpm, and SpO2 87% on room air. The patient is sitting upright, using accessory muscles, and has diffuse crackles bilaterally and jugular venous distention. Which of the following represents the most appropriate initial therapy?', '["Intubate the patient immediately and administer intravenous loop diuretics", "Administer albuterol-ipratropium nebulizer and oral metoprolol 25 mg", "Administer high-flow oxygen via non-rebreather mask and intravenous morphine 4 mg", "Administer intravenous nitroprusside infusion and normal saline bolus", "Initiate non-invasive positive pressure ventilation (BiPAP/CPAP) and administer intravenous nitroglycerin"]'::jsonb, 4, 'The patient is presenting with Acute Decompensated Heart Failure (ADHF) with acute pulmonary edema and sympathetic crash. The first-line therapeutic goals are to reduce work of breathing and decrease preload/afterload. Non-invasive positive pressure ventilation (NIPPV: CPAP or BiPAP) is highly effective: it increases intrathoracic pressure, reducing preload, and recruits collapsed alveoli, improving oxygenation. Intravenous nitroglycerin acts as a powerful venodilator to reduce preload and, at higher doses, an afterload reducer. Morphine should be avoided. (Ref: Tintinalli''s Ch. 53; Step-Up to EM Ch. 2; Case Files: EM Case 3)'),
    (v_topic_id, 'A 44-year-old female named Jessica presents to the Emergency Department triage room in severe respiratory distress. The patient has a history of congestive heart failure. Vitals are BP 182/110 mmHg, HR 132 bpm, RR 24 rpm, and SpO2 85% on room air. The patient is sitting upright, using accessory muscles, and has diffuse crackles bilaterally and jugular venous distention. Which of the following represents the most appropriate initial therapy?', '["Administer intravenous nitroprusside infusion and normal saline bolus", "Administer albuterol-ipratropium nebulizer and oral metoprolol 25 mg", "Administer high-flow oxygen via non-rebreather mask and intravenous morphine 4 mg", "Initiate non-invasive positive pressure ventilation (BiPAP/CPAP) and administer intravenous nitroglycerin", "Intubate the patient immediately and administer intravenous loop diuretics"]'::jsonb, 3, 'The patient is presenting with Acute Decompensated Heart Failure (ADHF) with acute pulmonary edema and sympathetic crash. The first-line therapeutic goals are to reduce work of breathing and decrease preload/afterload. Non-invasive positive pressure ventilation (NIPPV: CPAP or BiPAP) is highly effective: it increases intrathoracic pressure, reducing preload, and recruits collapsed alveoli, improving oxygenation. Intravenous nitroglycerin acts as a powerful venodilator to reduce preload and, at higher doses, an afterload reducer. Morphine should be avoided. (Ref: Tintinalli''s Ch. 53; Step-Up to EM Ch. 2; Case Files: EM Case 3)'),
